:root {
  --color-bg: #e8f0e4;
  --color-border: #7a9e6f;
  --color-header-bg: #4a7c42;
  --color-header-text: #f4f9f2;
  --color-title: #2b4e25;
  --color-plant-name: #2b4e25;
  --color-common: #6a8f61;
  --color-label-bg: #c7dbbf;
  --color-label-text: #3a6132;
  --color-value-text: #2b4e25;
  --color-footer-bg: #c7dbbf;
  --color-footer-text: #4a7c42;
  --color-id-text: #2b4e25;
}

.care-tag {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 10px;
  width: 280px;
  overflow: hidden;
  font-size: 14px;
}

.tag-header {
  background-color: var(--color-header-bg);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
}

.tag-icon {
  font-size: 20px;
  line-height: 1;
}

.tag-title {
  color: var(--color-header-text);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin: 0;
}

.tag-body {
  padding: 12px 14px;
}

.plant-name {
  color: var(--color-plant-name);
  font-size: 18px;
  font-weight: 700;
  font-style: italic;
  margin: 0 0 2px;
  line-height: 1.2;
}

.plant-common {
  color: var(--color-common);
  font-size: 12px;
  font-weight: 500;
  margin: 0 0 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.care-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.care-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.care-label {
  background-color: var(--color-label-bg);
  color: var(--color-label-text);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 2px 7px;
  border-radius: 4px;
  min-width: 60px;
  text-align: center;
}

.care-value {
  color: var(--color-value-text);
  font-size: 13px;
  font-weight: 500;
}

.tag-footer {
  background-color: var(--color-footer-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
  border-top: 1px solid var(--color-border);
}

.tag-date {
  color: var(--color-footer-text);
  font-size: 11px;
  font-weight: 500;
}

.tag-id {
  color: var(--color-id-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
}
